# movie_serie_genres


default_relation_types = [
    {"name": "Adaptation", "name_esp": "Adaptación", "description": "Basado en otra obra, normalmente manga, novelas ligeras o juegos."},
    {"name": "Alternative Setting", "name_esp": "Entorno Alternativo", "description": "Una historia que reimagina los personajes y la premisa en un universo o línea temporal diferente."},
    {"name": "Based On", "name_esp": "Basado En", "description": "Utilizado para el material de origen."},
    {"name": "Compilation", "name_esp": "Compilación", "description": "Similar a un resumen, pero puede implicar una reedición o contenido adicional."},
    {"name": "Original Story", "name_esp": "Historia Original", "description": "Indica que el anime o manga no está basado en una obra preexistente."},
    {"name": "Other", "name_esp": "Otros", "description": "Un tipo de relación menos común o específica."},
    {"name": "Prequel", "name_esp": "Precuela", "description": "Una historia que tiene lugar antes de los acontecimientos de un anime, película o manga anterior."},
    {"name": "Same Setting", "name_esp": "Mismo Entorno", "description": "tienen lugar en el mismo mundo pero pueden no ser secuelas o precuelas directas."},
    {"name": "Sequel", "name_esp": "Secuela", "description": "Continuación directa de una serie de anime, película o manga anterior."},
    {"name": "Side Story", "name_esp": "Historia Paralela", "description": "Historia que transcurre en el mismo universo que el anime, la película o el manga principal, pero que se centra en personajes o acontecimientos diferentes."},
    {"name": "Spin-Off", "name_esp": "Derivada", "description": "Una nueva serie que se ramifica, a menudo centrándose en un personaje o elemento específico."},
    {"name": "Remake", "name_esp": "Remake", "description": "Nueva versión de una obra anterior (cine, series, juegos)."},
    {"name": "Reboot", "name_esp": "Reinicio", "description": "Reinicio de una saga que vuelve a contar la historia desde cero."},
    {"name": "Crossover", "name_esp": "Cruce", "description": "Obra en la que se cruzan personajes o mundos de otras obras."},
    {"name": "Summary", "name_esp": "Resumen", "description": "Una colección que recapitula los acontecimientos de una serie."},
]






